 "content": "def transform(grid):
    """Clear the loose marker pixels and use their colors to checker-fill frames.

    Each solid rectangular outline receives the color whose loose-marker count
    matches the number of cells in that frame's even-parity checkerboard.
    """
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row if v != 0}

    # Find complete axis-aligned rectangular outlines, represented by bounds
    # and outline color. ARC fixtures here have a single-color perimeter.
    frames = []
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        if not pts:
            continue
        r0 = min(r for r, _ in pts); r1 = max(r for r, _ in pts)
        c0 = min(c for _, c in pts); c1 = max(c for _, c in pts)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r0, c) for c in range(c0, c1 + 1)} | {(r1, c) for c in range(c0, c1 + 1)}
        perimeter |= {(r, c0) for r in range(r0, r1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}
        if all(g[r][c] == color for r, c in perimeter):
            frames.append((r0, c0, r1, c1, color))

    # Distinguish outline colors from loose marker colors.
    frame_colors = {f[4] for f in frames}
    loose_counts = {}
    for r in range(h):
        for c in range(w):
            v = g[r][c]
            if v != 0 and v not in frame_colors:
                loose_counts[v] = loose_counts.get(v, 0) + 1

    # Remove loose markers; retain only the outlined objects before filling.
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0 and g[r][c] not in frame_colors:
                g[r][c] = 0

    # Each frame's intended count is the even-parity checkerboard population.
    for r0, c0, r1, c1, border_color in frames:
        cells = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
                 if ((r - (r0 + 1)) + (c - (c0 + 1))) % 2 == 0]
        matches = [color for color, count in loose_counts.items() if count == len(cells)]
        if len(matches) == 1:
            fill = matches[0]
            for r, c in cells:
                g[r][c] = fill
    return g
